window.Admin=(()=>{
 const {esc:e,icon,link,btn,heading,empty,badge,field,textarea,select}=UI;
 const names={categories:'Categories',subcategories:'Subcategories',children:'Child categories',papers:'Papers',jobs:'Jobs',years:'Job years'};
 const root=()=>MCQ.role()==='super-admin'?'super-admin':'admin';
 const url=p=>root()+'/'+p;
 const navLink=(p,title,i)=>link(url(p),icon(i)+e(title),'item '+(App.route.path===url(p)?'active':''));
 const can=perm=>MCQ.role()==='super-admin'||MCQ.hasPermission(perm);
 function shell(body,title){
  const superAdmin=MCQ.role()==='super-admin';
  const contentLinks=[
   navLink('mcqs',superAdmin?'All MCQs':'My MCQs','book'),
   can('add_mcq')?navLink('add','Add MCQ','plus'):'',
   navLink('pending','Pending review','clock'),navLink('approved','Approved','check'),navLink('rejected','Rejected','flag'),
   can('manage_categories')?navLink('categories','Categories','grid'):'',
   can('manage_papers')?navLink('papers','Papers','paper'):'',
   can('manage_jobs')?navLink('jobs','Jobs','briefcase'):'',
   can('manage_job_years')?navLink('years','Job Years','clock'):''
  ].join('');
  const bulkLinks=[
   can('manage_categories')?navLink('bulk-categories','Bulk Categories','upload'):'',
   can('manage_papers')?navLink('bulk-papers','Bulk Papers','upload'):'',
   can('manage_jobs')?navLink('bulk-jobs','Bulk Jobs','upload'):'',
   can('manage_job_years')?navLink('bulk-years','Bulk Job Years','upload'):'',
   MCQ.allowed('import')?navLink('import','Bulk MCQs','upload'):''
  ].join('');
  const superSections=superAdmin?`
   <div class="nav-label">Users</div>${navLink('users','Learners','user')}${navLink('admins','Admins','shield')}${navLink('roles','Permissions','shield')}${navLink('activity','Activity Logs','clock')}
   <div class="nav-label">Bulk Management</div>${bulkLinks}
   <div class="nav-label">Monetization</div>${navLink('adsense','Google AdSense','chart')}${navLink('custom-ads','Custom Ads','paper')}
   <div class="nav-label">Analytics</div>${navLink('google-analytics','Google Analytics','chart')}${navLink('analytics','Content Analytics','chart')}
   <div class="nav-label">Website</div>${navLink('settings','General Settings','settings')}${navLink('content','Site Content','edit')}${navLink('seo','SEO','globe')}
   <div class="nav-label">System</div>${navLink('reports','Reports','flag')}${navLink('trash','Trash & Recovery','archive')}${navLink('backup','Backup / Export','download')}
  `:`<div class="nav-label">Bulk Management</div>${bulkLinks}`;
  return `<div class="dash-layout"><aside class="sidebar" id="admin-sidebar">${UI.brand()}<div class="nav-label">${superAdmin?'Super Admin':'Admin'}</div>${navLink('overview','Dashboard','grid')}<div class="nav-label">Content</div>${contentLinks}${superSections}<div class="nav-label">Workspace</div>${link('home',icon('home')+' View Site','item')}${link('dashboard',icon('user')+' Learner View','item')}</aside><div class="dash-main"><header class="dash-top">${btn(icon('menu'),'sidebar','ghost menu-toggle','aria-label="Toggle admin sidebar" aria-expanded="false" aria-controls="admin-sidebar"')}<span class="small muted">Workspace / <strong>${e(title)}</strong></span><span class="spacer"></span><span class="badge">${superAdmin?'Super Admin':'Admin'}</span>${UI.userMenu()}</header><main class="dash-content" id="main" tabindex="-1">${body}</main></div></div>`;
 }
 const metrics=()=>{const d=MCQ.db;const today=new Date().toISOString().slice(0,10),month=today.slice(0,7);return [[d.mcqs.length,'Total MCQs'],[d.mcqs.filter(x=>x.status==='pending').length,'Pending review'],[d.mcqs.filter(x=>x.status==='approved').length,'Approved MCQs'],[d.mcqs.filter(x=>x.status==='rejected').length,'Rejected MCQs'],[d.papers.length,'Papers'],[d.jobs.length,'Jobs'],[d.years.length,'Job years'],[d.categories.length,'Categories'],[d.users.filter(x=>x.role==='user').length,'Learners'],[d.users.filter(x=>x.role!=='user').length,'Administrators'],[d.mcqs.filter(x=>x.created_at?.startsWith(today)).length,'Added today'],[d.mcqs.filter(x=>x.created_at?.startsWith(month)).length,'Added this month']]};
 function bars(type,field){const xs=MCQ.db[type].map(x=>({...x,count:MCQ.db.mcqs.filter(q=>MCQ.ids(q[field]).includes(x.id)).length})).sort((a,b)=>b.count-a.count).slice(0,5);return xs.map(x=>`<div class="bar-row"><div class="row"><span>${e(x.name)}</span><span>${x.count}</span></div><div class="progress-track"><span style="width:${x.count/Math.max(1,xs[0].count)*100}%"></span></div></div>`).join('')}
 function personalOverview(){
 const rows=MCQ.managedRows('mcqs'),activity=MCQ.managedRows('logs');
 const pending=rows.filter(q=>q.status==='pending'||q.pending_update).length;
 const approved=rows.filter(q=>q.status==='approved'&&!q.pending_update).length;
 const rejected=rows.filter(q=>q.status==='rejected'&&!q.pending_update).length;
 const cards=[[rows.length,'My MCQs'],[pending,'My pending'],[approved,'My approved'],[rejected,'My rejected']];
 const recent=[...rows].sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||''))).slice(0,5);
 return heading('My contribution','Your questions, review status and recorded activity.',link(url('add'),icon('plus')+' Add MCQ','btn primary'))+`<div class="metric-grid">${cards.map(([n,l])=>`<div class="card metric"><p>${l}</p><strong>${n.toLocaleString()}</strong></div>`).join('')}</div><section><div class="section-head"><h2>My recent questions</h2>${link(url('mcqs'),'My question library','link')}</div>${recent.length?table(recent,false):empty('No questions added yet','Questions created by your account will appear here.')}</section><section class="card" style="margin-top:20px"><h2>My recent activity</h2>${logs(10)}</section>`;
 }
 function overview(){
  if(MCQ.role()==='admin')return personalOverview();
  const d=MCQ.db;
  const cards=[
   [d.mcqs.length,'Total MCQs','book'],
   [MCQ.categoryCounts().categories,'Categories','grid'],
   [d.papers.length,'Papers','paper'],
   [d.jobs.length,'Jobs','briefcase'],
   [d.users.filter(x=>x.role==='user').length,'Learners','user'],
   [d.users.filter(x=>x.role!=='user').length,'Admins','shield']
  ];
  const recentMcqs=[...d.mcqs].sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||''))).slice(0,5);
  const recentUsers=[...d.users].sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||''))).slice(0,5);
  const quick=[link(url('add'),icon('plus')+' Add MCQ','btn primary'),link(url('bulk-categories'),'Bulk Categories','btn'),link(url('google-analytics'),'Google Analytics','btn'),link(url('adsense'),'AdSense','btn')].join('');
  return heading('MCQ Campus control center','Important platform information and quick actions without dashboard clutter.',quick)+
   `<div class="metric-grid admin-primary-metrics">${cards.map(([n,l,i])=>`<div class="card metric"><div class="actions"><p>${l}</p><span class="spacer"></span><span class="tile-icon">${icon(i)}</span></div><strong>${UI.counter(n)}</strong></div>`).join('')}</div>
   <div class="split admin-overview-main"><section><div class="section-head"><h2>Recently added MCQs</h2>${link(url('mcqs'),'View all','link')}</div>${recentMcqs.length?table(recentMcqs,false):empty('No MCQs found')}</section>
   <section class="card"><h3>Recent admin activity</h3>${logs(7)}</section></div>
   <div class="split admin-overview-bottom"><div class="card"><h3>Recent users</h3>${recentUsers.length?`<ul class="activity">${recentUsers.map(x=>`<li><strong>${e(x.name||x.email)}</strong><small>${e(x.role)} · ${UI.date(x.created_at)}</small></li>`).join('')}</ul>`:'<p class="small muted">No recent users.</p>'}</div>
   <div class="card"><h3>Quick actions</h3><div class="actions">${quick}</div><p class="small muted">Management tools are grouped in the sidebar instead of crowding the dashboard.</p></div></div>`;
 }
 function logs(limit=30){const rows=MCQ.managedRows('logs').slice(0,limit);return rows.length?`<ul class="activity">${rows.map(x=>`<li><strong>${e(x.action)}</strong> · ${e(x.detail)}<small>${e(x.by)} · ${UI.date(x.at)}</small></li>`).join('')}</ul>`:'<p class="muted small">Your management activity will appear here.</p>'}
 function submissionBadge(q){if(q.pending_update)return badge('UPDATE','warning');if(q.submission_type==='duplicate')return badge('DUPLICATE','danger');return badge(q.status==='pending'?'NEW':(q.submission_type||q.status),q.status==='pending'?'success':q.status)}
 function table(rows,bulk=true){return `<div class="table-wrap mobile-cards"><table><thead><tr>${bulk?'<th><input type="checkbox" data-action="select-all" aria-label="Select all visible rows"></th>':''}<th>Question</th><th>Submission</th><th>Submitted by</th><th>Category</th><th>Status</th><th>Created / updated (PKT)</th><th>Actions</th></tr></thead><tbody>${rows.map(q=>{const pu=q.pending_update;return `<tr>${bulk?`<td><input type="checkbox" class="row-check" value="${q.id}" aria-label="Select question ${q.id}"></td>`:''}<td data-label="Question"><strong>${e(pu?.proposed?.question||q.question)}</strong><div class="small muted">#${q.id}</div></td><td data-label="Submission">${submissionBadge(q)}</td><td data-label="Submitted by">${e(pu?.submitted_by||q.submitted_by||q.created_by||'—')}</td><td data-label="Category">${e(MCQ.get('categories',pu?.proposed?.category_id||q.category_id)?.name||'—')}</td><td data-label="Status">${badge(pu?'pending':q.status)}</td><td data-label="Created / updated">Created: ${UI.date(q.created_at)}<br>Updated: ${UI.date(q.updated_at)}<br><span class="small muted">By ${e(q.created_by||'Unknown')}</span></td><td><div class="table-actions">${btn('Read / review','view-mcq','sm',`data-id="${q.id}"`)}${link(url('edit/'+q.id),'Edit','btn sm')}${MCQ.allowed('review')&&(q.status!=='approved'||pu)?btn('Approve','review','sm',`data-id="${q.id}" data-status="approved"`):''}</div></td></tr>`}).join('')}</tbody></table></div>`}
 function mcqs(view){let rows=MCQ.managedRows('mcqs');const p=App.route.params;if(view==='pending')rows=rows.filter(q=>q.status==='pending'||q.pending_update);else if(['approved','rejected'].includes(view))rows=rows.filter(q=>q.status===view&&!q.pending_update);else if(p.status)rows=rows.filter(q=>q.status===p.status);if(view==='duplicates'){const counts={};MCQ.db.mcqs.forEach(q=>counts[MCQ.norm(q.question)]=(counts[MCQ.norm(q.question)]||0)+1);rows=rows.filter(q=>counts[MCQ.norm(q.question)]>1)}if(p.q)rows=rows.filter(q=>MCQ.norm(q.question).includes(MCQ.norm(p.q)));if(p.category)rows=rows.filter(q=>q.category_id===+p.category);if(MCQ.role()==='super-admin'){if(p.author)rows=rows.filter(q=>p.author==='unknown'?!q.created_by_id:+q.created_by_id===+p.author);if(p.paper)rows=rows.filter(q=>MCQ.ids(q.paper_id).includes(+p.paper));if(p.job)rows=rows.filter(q=>MCQ.ids(q.job_ids).includes(+p.job));if(p.from)rows=rows.filter(q=>(q.created_at||'').slice(0,10)>=p.from);if(p.to)rows=rows.filter(q=>q.created_at&&(q.created_at||'').slice(0,10)<=p.to);}rows=[...rows].sort((a,b)=>p.sort==='question'?a.question.localeCompare(b.question):b.id-a.id);const allowedPageSizes=MCQ.role()==='super-admin'?[10,20,50,100,500,1000,2000,3000]:[10,20,50,100];const defaultPageSize=MCQ.role()==='super-admin'?20:20;const pageSize=allowedPageSizes.includes(+p.limit)?+p.limit:defaultPageSize;const page=App.page(rows.length,pageSize);return heading(view==='mcqs'?'Question library':view==='duplicates'?'Duplicate questions':view[0].toUpperCase()+view.slice(1)+' MCQs',`${rows.length} records · Search, review and maintain your collection.`,link(url('add'),icon('plus')+' Add MCQ','btn primary'))+`<div class="tabs">${[['mcqs','All questions'],['pending','Pending'],['approved','Approved'],['rejected','Rejected']].map(([p,n])=>link(url(p),n,p===view?'active':'')).join('')}</div><form class="toolbar" data-form="filter">${UI.search('Search questions',p.q||'')}<select name="category" aria-label="Filter category"><option value="">All categories</option>${MCQ.db.categories.map(c=>`<option value="${c.id}" ${+p.category===c.id?'selected':''}>${e(c.name)}</option>`).join('')}</select><select name="status" aria-label="Filter status"><option value="">All statuses</option>${['pending','approved','rejected'].map(s=>`<option ${p.status===s?'selected':''}>${s}</option>`).join('')}</select>${MCQ.role()==='super-admin'?`<select name="author" aria-label="Filter creator"><option value="">All creators</option><option value="unknown" ${p.author==='unknown'?'selected':''}>Unassigned / legacy owner</option>${MCQ.db.users.filter(u=>u.role!=='user').map(u=>`<option value="${u.id}" ${+p.author===u.id?'selected':''}>${e(u.name)}</option>`).join('')}</select><select name="paper" aria-label="Filter paper"><option value="">All papers</option>${MCQ.db.papers.map(x=>`<option value="${x.id}" ${+p.paper===x.id?'selected':''}>${e(x.name)}</option>`).join('')}</select><select name="job" aria-label="Filter job"><option value="">All jobs</option>${MCQ.db.jobs.filter(x=>!p.paper||+x.paper_id===+p.paper).map(x=>`<option value="${x.id}" ${+p.job===x.id?'selected':''}>${e(x.name)}</option>`).join('')}</select><label>Created from <input type="date" name="from" value="${e(p.from||'')}"></label><label>Created to <input type="date" name="to" value="${e(p.to||'')}"></label>`:''}<label class="admin-page-size"><span>Show</span><select name="limit" aria-label="MCQs per page">${allowedPageSizes.map(n=>`<option value="${n}" ${pageSize===n?'selected':''}>${n.toLocaleString()}</option>`).join('')}</select><span>MCQs per page</span></label></form>${MCQ.allowed('review')?`<div class="toolbar"><span class="small muted" id="selection-count">0 selected</span>${btn('Approve selected','bulk-review','sm','data-status="approved"')}${btn('Reject selected','bulk-review','sm danger','data-status="rejected"')}${btn('Send for correction','bulk-review','sm','data-status="pending"')}</div>`:''}${rows.length?table(rows.slice((page-1)*pageSize,page*pageSize))+UI.pager(rows.length,page,pageSize,p):empty(view==='duplicates'?'No duplicate questions':'No matching questions',view==='duplicates'?'Exact normalized question matches will appear here.':'Try another search or status filter.')}`}
 const pickerDefs={category_id:['categories','Category',false],subcategory_ids:['subcategories','Subcategories',true],child_subcategory_ids:['children','Child categories',true],paper_id:['papers','Papers',true],job_ids:['jobs','Jobs',true],job_years_ids:['years','Job years',true]};
 function picker(name){const [type,label,multi]=pickerDefs[name];const vals=MCQ.ids(App.draft[name]);return `<div class="field"><label for="pick-${name}">${label} *</label><div class="picker" data-picker="${name}"><input id="pick-${name}" type="search" placeholder="Search ${label.toLowerCase()}…" aria-label="Search ${label.toLowerCase()}" autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="results-${name}" data-picker-input="${name}"><div class="picker-results hidden" id="results-${name}" role="listbox"></div></div><div class="chips" data-chip-area="${name}">${vals.map(id=>`<span class="chip" draggable="true" data-chip="${name}" data-id="${id}">${e(MCQ.get(type,id)?.name||id)}<button type="button" data-action="remove-chip" data-field="${name}" data-id="${id}" aria-label="Remove ${e(MCQ.get(type,id)?.name)}">×</button></span>`).join('')}</div><small>${multi?'Select one or more. Drag chips to reorder.':'Select one category.'}</small></div>`}
 function form(id){const existing=id?MCQ.managedRows('mcqs').find(q=>q.id===+id):null;if(id&&!existing)return empty('Question not found');if(App.draftKey!==String(id||'new')){App.draft=existing?MCQ.clone(existing):{question:'',option1:'',option2:'',option3:'',option4:'',correct_answer:'',description:'',category_id:'',subcategory_ids:[],child_subcategory_ids:[],paper_id:[],job_ids:[],job_years_ids:[]};App.draftKey=String(id||'new')}
 const q=App.draft;return heading(existing?'Edit question':'Add a new question','Create a clear question, set the answer, and connect it to the right collections.',link(url('mcqs'),'Back to library','btn'))+`<div class="notice">${MCQ.role()==='admin'?'New and edited questions are sent to Pending review.':'New questions start as Pending. Approve them from the review queue.'} Changes save in this browser demo.</div><form data-form="mcq" id="mcq-form"><div class="split"><div><section class="card"><p class="eyebrow">01 · THE QUESTION</p>${textarea('question','Question',q.question,true)}<div id="question-duplicate"></div><div class="form-grid">${[1,2,3,4].map(i=>field('option'+i,'Option '+i,q['option'+i],'text',true)).join('')}</div><div class="field"><label for="answer-select">Correct answer *</label><select id="answer-select" name="correct_answer" required><option value="">Choose the correct option</option>${[1,2,3,4].filter(i=>q['option'+i]).map(i=>`<option value="${e(q['option'+i])}" ${q.correct_answer===q['option'+i]?'selected':''}>${'ABCD'[i-1]} · ${e(q['option'+i])}</option>`).join('')}</select></div>${textarea('description','Explanation / description',q.description)}${field('source','Source / reference',q.source||'','text',false,'placeholder="Official paper, book, website or document"')}${field('seo_description','SEO description',q.seo_description||'','text',false,'maxlength="160" placeholder="Optional concise search description"')}<label class="check-line"><input type="checkbox" name="important" ${q.important?'checked':''}> Mark as important</label></section><section class="card" style="margin-top:22px"><p class="eyebrow">02 · SUBJECT CLASSIFICATION</p><div id="subject-pickers">${['category_id','subcategory_ids','child_subcategory_ids'].map(picker).join('')}</div></section></div><div><section class="card"><p class="eyebrow">03 · PAST PAPER LINKS</p><div id="paper-pickers">${['paper_id','job_ids','job_years_ids'].map(picker).join('')}</div></section><section class="card" style="margin-top:22px"><h3>Content quality</h3>${(()=>{const z=MCQ.contentQuality(q);return `<div class="quality-score"><strong>${z.score}/${z.total}</strong><span>completeness checks</span></div><div class="quality-list">${z.checks.map(x=>`<span class="${x.ok?'ok':'missing'}">${x.ok?'✓':'○'} ${e(x.label)}</span>`).join('')}</div>`})()}<hr><h3>Ready for review</h3><p class="small muted">Check that the answer exactly matches one of the four options.</p><button type="submit" class="btn primary" style="width:100%;margin-top:18px">${existing?'Save changes':'Save question'}</button><div class="actions" style="margin-top:10px">${btn('Preview question','preview-draft','sm')}${btn('Clear form','clear-draft','sm')}</div><div id="mcq-errors" role="alert" style="margin-top:15px"></div>${existing?`<hr><p class="small">Created by: ${e(existing.created_by)}<br>Reviewed by: ${e(existing.reviewed_by||'Not reviewed')}<br>Approved by: ${e(existing.approved_by||'—')}<br>Updated: ${UI.date(existing.updated_at)}</p>${existing.rejection_reason?`<div class="notice warning">${e(existing.rejection_reason)}</div>`:''}`:''}</section></div></div></form>`}
 function syncDraft(){const f=document.getElementById('mcq-form');if(!f)return;const data=new FormData(f);for(const k of ['question','option1','option2','option3','option4','correct_answer','description','source','seo_description'])App.draft[k]=String(data.get(k)||'');App.draft.important=data.has('important')}
 function refreshPickers(){document.getElementById('subject-pickers').innerHTML=['category_id','subcategory_ids','child_subcategory_ids'].map(picker).join('');document.getElementById('paper-pickers').innerHTML=['paper_id','job_ids','job_years_ids'].map(picker).join('')}
 function pickerOptions(field,q=''){const [type,,multi]=pickerDefs[field];let rows=MCQ.db[type];const d=App.draft,ids=MCQ.ids;if(field==='subcategory_ids')rows=rows.filter(x=>x.category_id===+d.category_id);if(field==='child_subcategory_ids')rows=rows.filter(x=>ids(d.subcategory_ids).includes(x.subcategory_id));if(field==='job_ids')rows=rows.filter(x=>ids(d.paper_id).includes(x.paper_id));if(field==='job_years_ids')rows=rows.filter(x=>ids(d.job_ids).includes(x.job_id));return rows.filter(x=>MCQ.norm(x.name).includes(MCQ.norm(q))&&!ids(d[field]).includes(x.id)).sort((a,b)=>(MCQ.norm(b.name)===MCQ.norm(q))-(MCQ.norm(a.name)===MCQ.norm(q))||a.name.localeCompare(b.name)).slice(0,40)}
 function showPicker(input){const f=input.dataset.pickerInput,res=document.getElementById('results-'+f),rows=pickerOptions(f,input.value);res.innerHTML=rows.length?rows.map(x=>`<button type="button" role="option" aria-selected="false" data-action="pick" data-field="${f}" data-id="${x.id}">${e(x.name)}</button>`).join(''):'<p class="small muted" style="padding:10px">No matches. Select the parent first, or create a record in management.</p>';res.classList.remove('hidden');input.setAttribute('aria-expanded','true')}
 function pick(f,id,remove=false){syncDraft();const multi=pickerDefs[f][2];if(remove)App.draft[f]=multi?MCQ.ids(App.draft[f]).filter(x=>x!==+id):'';else App.draft[f]=multi?[...new Set([...MCQ.ids(App.draft[f]),+id])]:+id;const d=App.draft;if(f==='category_id'){d.subcategory_ids=[];d.child_subcategory_ids=[]}if(f==='subcategory_ids')d.child_subcategory_ids=MCQ.ids(d.child_subcategory_ids).filter(id=>MCQ.ids(d.subcategory_ids).includes(MCQ.get('children',id)?.subcategory_id));if(f==='paper_id'){d.job_ids=MCQ.ids(d.job_ids).filter(id=>MCQ.ids(d.paper_id).includes(MCQ.get('jobs',id)?.paper_id))}if(['paper_id','job_ids'].includes(f))d.job_years_ids=MCQ.ids(d.job_years_ids).filter(id=>MCQ.ids(d.job_ids).includes(MCQ.get('years',id)?.job_id));refreshPickers()}
 function entities(type){const p=App.route.params,rel=MCQ.parents[type];let rows=MCQ.list(type,p.q||'');if(p.parent&&rel)rows=rows.filter(x=>x[rel[1]]===+p.parent);rows=[...rows].sort((a,b)=>p.sort==='new'?b.id-a.id:a.name.localeCompare(b.name));const page=App.page(rows.length);return heading(names[type],`${rows.length} records · Exact matches are reused within their parent collection.`,btn(icon('plus')+' Add '+names[type].toLowerCase(),'entity-new','primary',`data-type="${type}"`))+`<form class="toolbar" data-form="filter">${UI.search('Search '+names[type].toLowerCase(),p.q||'')}${rel?`<select name="parent" aria-label="Filter parent"><option value="">All ${names[rel[0]].toLowerCase()}</option>${MCQ.db[rel[0]].map(x=>`<option value="${x.id}" ${+p.parent===x.id?'selected':''}>${e(x.name)}</option>`).join('')}</select>`:''}<select name="sort" aria-label="Sort records"><option value="">Name A–Z</option><option value="new" ${p.sort==='new'?'selected':''}>Newest first</option></select></form>${rows.length?`<div class="table-wrap mobile-cards"><table><thead><tr><th>Name</th><th>Icon</th><th>Status</th>${rel?'<th>Parent</th>':''}${type==='years'?'<th>Total MCQs</th>':''}<th>ID</th><th>Created / updated (PKT)</th><th>Actions</th></tr></thead><tbody>${rows.slice((page-1)*12,page*12).map(x=>`<tr><td data-label="Name"><strong>${e(x.name)}</strong>${x.legacy?'<div class="small muted">Legacy · retained for existing MCQs</div>':''}</td><td data-label="Icon"><span class="admin-icon-cell">${UI.entityIcon(x,'grid')}</span></td><td data-label="Status">${badge(x.active===false?'disabled':'active',x.active===false?'rejected':'approved')}</td>${rel?`<td data-label="Parent">${e(MCQ.get(rel[0],x[rel[1]])?.name)}</td>`:''}${type==='years'?`<td data-label="Total MCQs"><strong>${MCQ.db.mcqs.filter(q=>MCQ.ids(q.job_years_ids).includes(x.id)).length}</strong></td>`:''}<td data-label="ID">${x.id}</td><td data-label="Created / updated">${UI.date(x.created_at)}<br>${e(x.created_by||'Unknown')}<br>Updated: ${UI.date(x.updated_at)}<br>${e(x.updated_by||'Unknown')}</td><td><div class="table-actions">${link(({categories:'category',subcategories:'subcategory',children:'topic',papers:'paper',jobs:'job',years:'year'})[type]+'/'+x.id,'View','btn sm')}${btn('Edit','entity-edit','sm',`data-type="${type}" data-id="${x.id}"`)}${MCQ.role()==='super-admin'?btn(icon('trash')+' Delete','entity-delete','sm danger',`data-type="${type}" data-id="${x.id}"`):''}</div></td></tr>`).join('')}</tbody></table></div>${UI.pager(rows.length,page,12,p)}`:empty('No matching records','Add a record or try a different search.')}`}
 function entityModal(type,id){MCQ.assert('taxonomy');const x=MCQ.get(type,id)||{},parent=MCQ.parents[type];UI.modal(id?'Edit '+names[type].toLowerCase():'Add '+names[type].toLowerCase(),`<form data-form="entity" data-type="${type}" data-id="${id||''}">${field('entity-name','Name',x.name||'','text',true)}<div class="field"><label>Icon</label><div class="icon-editor"><div class="icon-preview" id="entity-icon-preview">${UI.entityIcon(x,'grid')}</div><div class="grow">${field('entity-icon','Characters / emoji',/^data:image\/png;base64,/i.test(String(x.icon||''))?'':(x.icon||''),'text',false,'maxlength="4" placeholder="1–4 characters, e.g. CS or 📚"')}<label class="btn sm" for="entity-icon-file">Upload PNG</label><input class="visually-hidden" id="entity-icon-file" type="file" accept="image/png"><input type="hidden" name="entity-icon-data" value="${/^data:image\/png;base64,/i.test(String(x.icon||''))?e(x.icon):''}"><p class="small muted">Use either 1–4 characters/emoji or a PNG. Typing characters replaces the PNG.</p></div></div></div><label class="check-line"><input type="checkbox" name="entity-active" ${x.active!==false?'checked':''}> Enabled / visible</label>${parent?`<div class="field"><label for="entity-parent-search">Find parent</label><input id="entity-parent-search" type="search" placeholder="Type to filter parent records" data-parent-search="${type}"></div>${select('entity-parent','Parent '+names[parent[0]].toLowerCase(),MCQ.db[parent[0]],x[parent[1]]||'',true)}`:''}<div id="entity-state" role="status"></div><div class="actions"><button class="btn primary">Save record</button>${id&&MCQ.role()==='super-admin'?btn(icon('trash')+' Delete','entity-delete','danger',`data-type="${type}" data-id="${id}"`):''}${btn('Cancel','close','')}</div></form>`)}
 function entityState(){const f=document.querySelector('form[data-form="entity"]');if(!f)return;const type=f.dataset.type,id=f.dataset.id,name=f.querySelector('[name="entity-name"]').value,parent=f.querySelector('[name="entity-parent"]')?.value;const dup=MCQ.duplicate(type,name,parent,id);const el=document.getElementById('entity-state');if(dup)el.innerHTML=`<div class="notice warning"><strong>Already exists: ${e(dup.name)}</strong><div class="actions" style="margin-top:10px">${btn('Use existing','use-entity','sm',`data-type="${type}" data-id="${dup.id}"`)}${btn('Edit existing','entity-edit','sm',`data-type="${type}" data-id="${dup.id}"`)}${link(({categories:'category',subcategories:'subcategory',children:'topic',papers:'paper',jobs:'job',years:'year'})[type]+'/'+dup.id,'View','btn sm')}</div></div>`;else{const possible=MCQ.list(type,name).filter(x=>name&&x.id!==+id).slice(0,3);el.innerHTML=name?`<div class="notice ${possible.length?'warning':'success'}">${possible.length?'Possible match: '+possible.map(x=>e(x.name)).join(' · '):'New record. No exact match.'}</div>`:''}}
 function importPage(){return heading('Bring your questions together','Upload a TXT, CSV or JSON file. Review every row before importing.')+`<div class="notice">Imports save Pending MCQs in this local demo. Names must match an existing hierarchy; use IDs for an exact mapping.</div><div class="steps">${['Upload','Parse','Preview','Validate','Duplicate check','Import'].map((s,i)=>`<span class="step ${App.importRows&&i<5?'done':''}">${i+1}. ${s}</span>`).join('')}</div><div class="card"><div class="section-head"><h3>Choose your file</h3><div class="actions">${['txt','csv','json'].map(ext=>btn(ext.toUpperCase()+' template','import-template','sm',`data-ext="${ext}"`)).join('')}</div></div><div class="dropzone" id="dropzone"><span class="tile-icon">${icon('upload')}</span><h3>Drop a file here, or browse</h3><p class="small muted">UTF-8 TXT, CSV or JSON · up to 5 MB</p><input type="file" id="import-file" accept=".txt,.csv,.json" aria-label="Upload MCQ file"></div><div id="import-results">${App.importRows?importPreview():'<p class="small muted">Each question needs four options, a matching correct answer, and complete category and paper links.</p>'}</div></div>`}
 function importPreview(){const rows=App.importRows||[],s=App.importSummary||{total:rows.length,valid:rows.filter(x=>x.status==='valid').length,imported:0,duplicates:rows.filter(x=>x.status==='duplicate').length,invalid:rows.filter(x=>x.status==='invalid').length,failed:0};return `<div class="status-grid">${Object.entries(s).map(([l,n])=>`<div class="card"><span class="small muted">${l[0].toUpperCase()+l.slice(1)}</span><strong>${n}</strong></div>`).join('')}</div><div class="toolbar" style="margin-top:20px">${btn('Import '+rows.filter(r=>r.status==='valid').length+' valid rows','import-commit','primary',rows.some(r=>r.status==='valid')?'':'disabled')}${btn('Download validation report','import-report','')}<span class="small muted">Duplicates are skipped. Invalid rows are not imported.</span></div><div class="table-wrap mobile-cards"><table><thead><tr><th>Row</th><th>Question</th><th>Result</th><th>Validation</th></tr></thead><tbody>${rows.slice(0,100).map(r=>`<tr><td data-label="Row">${r.line}</td><td data-label="Question">${e(r.question)}</td><td data-label="Status">${badge(r.status,r.status==='invalid'||r.status==='failed'?'rejected':r.status==='valid'||r.status==='imported'?'approved':'pending')}</td><td data-label="Validation">${r.errors.map(e).join(' ')}${r.existing?link(url('edit/'+r.existing),'Open existing','btn sm'):''}</td></tr>`).join('')}</tbody></table></div>${rows.length>100?'<p class="small muted">Showing the first 100 rows. Download the report for all rows.</p>':''}`}
 async function loadFile(file){if(!file)return;if(file.size>5*1024*1024){UI.toast('Choose a file smaller than 5 MB.');return}const box=document.getElementById('import-results');box.innerHTML='<div class="skeleton" role="status" aria-label="Parsing file"></div>';try{const raw=Importer.parse(await file.text(),file.name.split('.').pop().toLowerCase());if(raw.length>10000)throw Error('Use at most 10,000 rows per demo import.');App.importSummary=null;App.importRows=Importer.preview(raw);box.innerHTML=importPreview()}catch(err){App.importRows=null;box.innerHTML=`<div class="notice error" role="alert">${e(err.message)}</div>`}}
 function users(view){const rows=MCQ.db.users.filter(x=>view==='admins'?x.role!=='user':x.role==='user');return heading(view==='admins'?'Administrators':'Learners','Manage demo accounts and status.',btn(icon('plus')+' Add account','user-new','primary'))+`<div class="table-wrap mobile-cards"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Created / updated (PKT)</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr><td data-label="Name">${e(x.name)}</td><td data-label="Email">${e(x.email)}</td><td data-label="Role">${e(x.role)}</td><td data-label="Status">${badge(x.status==='active'?'approved':'rejected')}</td><td data-label="Created / updated">${UI.date(x.created_at)} · ${e(x.created_by||'Unknown')}<br>${UI.date(x.updated_at)} · ${e(x.updated_by||'Unknown')}</td><td>${btn('Edit','user-edit','sm',`data-id="${x.id}"`)}</td></tr>`).join('')}</tbody></table></div>`}
 function userModal(id){MCQ.assert('system');const x=MCQ.get('users',id)||{};UI.modal(id?'Edit demo account':'Add demo account',`<form data-form="user" data-id="${id||''}">${field('name','Name',x.name||'','text',true)}${field('email','Email',x.email||'','email',true)}${select('role','Role',['user','admin','super-admin'].map(x=>({id:x,name:x})),x.role||'user',true)}${select('status','Status',['active','disabled'].map(x=>({id:x,name:x})),x.status||'active',true)}<p class="small muted">No invitations are sent. No passwords are stored.</p><button class="btn primary">Save account</button></form>`)}
 function reports(){const d=MCQ.db;return heading('Reports & messages','Review question feedback and locally drafted contact messages.')+`<h2>Question reports</h2>${d.reports.length?`<div class="question-list">${d.reports.map(r=>`<div class="card"><div class="actions"><h3>${e(MCQ.get('mcqs',r.mcq_id)?.question)}</h3><span class="spacer"></span>${badge(r.status)}</div><p>${e(r.reason)}</p><div class="card-foot"><span>${UI.date(r.at)} · ${e(r.by||'Unknown')}</span><div class="actions">${link(url('edit/'+r.mcq_id),'Edit MCQ','btn sm')}${r.status!=='resolved'?btn('Resolve','report-resolve','sm',`data-id="${r.id}"`):''}</div></div></div>`).join('')}</div>`:empty('No question reports','Reports submitted from practice pages will appear here.')}<h2 style="margin-top:28px">Contact drafts</h2>${d.contacts.length?`<div class="question-list">${d.contacts.map(c=>`<div class="card"><h3>${e(c.subject)}</h3><p>${e(c.message)}</p><div class="card-foot"><span>${e(c.name)} · ${e(c.email)} · ${UI.date(c.at)}</span><span>Not sent</span></div></div>`).join('')}</div>`:empty('No contact drafts')}`}
 function guideManager(){return heading('Study guides','Write and edit the guides shown on the public website.',btn(icon('plus')+' Add guide','guide-new','primary'))+`<div class="grid">${MCQ.db.guides.map(g=>`<div class="card"><span class="eyebrow">${e(g.tag)}</span><h3>${e(g.name)}</h3><p>${e(g.summary)}</p><p class="small muted">Created: ${UI.date(g.created_at)} · ${e(g.created_by||'Unknown')}<br>Updated: ${UI.date(g.updated_at)} · ${e(g.updated_by||'Unknown')}</p><div class="card-foot">${link('guide/'+g.id,'View','link')}${btn('Edit','guide-edit','sm',`data-id="${g.id}"`)}</div></div>`).join('')}</div>`}
 function guideModal(id){MCQ.assert('system');const g=MCQ.get('guides',id)||{};UI.modal(id?'Edit guide':'Add guide',`<form data-form="guide" data-id="${id||''}">${field('name','Title',g.name||'','text',true)}${field('tag','Section label',g.tag||'STUDY SKILLS','text',true)}${textarea('summary','Summary',g.summary||'',true)}${textarea('body','Guide text',g.body||'',true)}<p class="small muted">Separate paragraphs with a blank line.</p><button class="btn primary">Save guide</button></form>`)}
 function postManager(){const rows=[...(MCQ.db.posts||[])].sort((a,b)=>String(b.updated_at||b.created_at||'').localeCompare(String(a.updated_at||a.created_at||'')));return heading('Posts','Publish useful text and links that can lead readers into MCQ practice.',btn(icon('plus')+' Add post','post-new','primary'))+(rows.length?`<div class="post-grid">${rows.map(post=>`<div class="card post-card"><div class="actions"><span class="eyebrow">${post.published!==false?'PUBLISHED':'DRAFT'}</span><span class="spacer"></span>${badge(post.published!==false?'published':'draft',post.published!==false?'success':'warning')}</div><h3>${e(post.title)}</h3><p>${e(post.excerpt||String(post.body||'').slice(0,150))}</p><p class="small muted">${(post.links||[]).length} link${(post.links||[]).length===1?'':'s'} · Updated ${UI.date(post.updated_at||post.created_at)}</p><div class="card-foot">${post.published!==false?link('post/'+post.id,'View','link'):''}${btn('Edit','post-edit','sm',`data-id="${post.id}"`)}</div></div>`).join('')}</div>`:empty('No posts yet','Add the first text post with useful links.'))}
 function postModal(id){MCQ.assert('system');const p=MCQ.get('posts',id)||{};const links=(p.links||[]).map(x=>`${x.label||x.url} | ${x.url}`).join('\n');UI.modal(id?'Edit post':'Add post',`<form data-form="post" data-id="${id||''}">${field('title','Post title',p.title||'','text',true)}${field('slug','Slug',p.slug||MCQ.slug(p.title||''),'text',false,'placeholder="auto-generated-from-title"')}${textarea('excerpt','Short summary',p.excerpt||'')}${textarea('body','Post text',p.body||'',true)}${field('featured_image','Featured image URL',p.featured_image||'','url')}${field('category','Post category',p.category||'Exam preparation','text')}${field('seo_title','SEO title',p.seo_title||'','text',false,'maxlength="70"')}${textarea('seo_description','SEO description',p.seo_description||'')}${textarea('links','Links',links)}<p class="small muted">One link per line: Label | https://example.com/page. Internal links can use #/mcqs, #/important, #/year/926 etc.</p>${select('status','Status',[{id:'draft',name:'Draft'},{id:'published',name:'Published'},{id:'scheduled',name:'Scheduled'},{id:'archived',name:'Archived'}],p.status||(p.published!==false?'published':'draft'),true)}<button class="btn primary">Save post</button></form>`) }


 function config(view){
  const d=MCQ.db;let fields='',title='',desc='';
  if(view==='roles'){title='Roles & permissions';desc='Control what Admin accounts can do. Backend authorization remains authoritative.';fields=`<h3>Admin permissions</h3><label class="check-line"><input name="review" type="checkbox" ${d.rolePermissions.admin.review?'checked':''}> Review/approve/reject MCQs</label><label class="check-line"><input name="import" type="checkbox" ${d.rolePermissions.admin.import?'checked':''}> Bulk import MCQs</label><div class="permission-grid">${MCQ.permissionCatalog.map(key=>`<label class="check-line"><input name="perm_${key}" type="checkbox" ${d.rolePermissions.admin.permissions?.[key]?'checked':''}> ${e(key.replaceAll('_',' ').replace(/^./,x=>x.toUpperCase()))}</label>`).join('')}</div>`;}
  if(view==='settings'){title='Website settings';desc='Core public website configuration.';fields=`${field('siteName','Website name',d.settings.siteName,'text',true)}${textarea('description','Site description',d.settings.description,true)}${field('country','Default country',d.settings.country,'text',true)}`;}
  if(view==='seo'){title='Search appearance';desc='Default SEO title and description.';fields=`${field('title','Default title',d.seo.title,'text',true)}${textarea('description','Meta description',d.seo.description,true)}`;}
  if(view==='content'){title='Site content';desc='Edit the main About and Contact introductions.';fields=`${textarea('about','About page introduction',d.content.about,true)}${textarea('contact','Contact page introduction',d.content.contact,true)}`;}
  if(view==='google-analytics'){title='Google Analytics';desc='Connect Analytics without editing HTML. Only the validated Measurement ID is stored.';fields=`${field('google_analytics_id','Measurement ID',d.settings.googleAnalyticsId||'','text',false,'placeholder="G-XXXXXXXXXX" pattern="G-[A-Za-z0-9]+"')}<label class="check-line"><input name="analytics_enabled" type="checkbox" ${d.settings.analyticsEnabled?'checked':''}> Enable Google Analytics</label><div class="notice">The public Django template loads Google Analytics only when this setting is enabled and a valid Measurement ID exists.</div>`;}
  if(view==='adsense'){title='Google AdSense';desc='Connect the AdSense client and manage ad slots separately.';fields=`${field('adsense_client_id','AdSense client / publisher ID',d.settings.adsenseClientId||'','text',false,'placeholder="ca-pub-1234567890123456"')}<label class="check-line"><input name="adsense_enabled" type="checkbox" ${d.settings.adsenseEnabled?'checked':''}> Enable Google AdSense</label><div class="notice">Only a validated ca-pub ID is stored. Arbitrary JavaScript is not executed.</div>`;}
  return heading(title,desc)+`<div class="card" style="max-width:850px"><form data-form="config" data-view="${view}">${fields}<button class="btn primary">Save changes</button></form></div>`;
 }
 function adForm(provider='custom'){
  const custom=provider==='custom';
  return `<form data-form="ad" class="card ad-editor"><input type="hidden" name="provider" value="${provider}">${field('name',custom?'Brand / company name':'Slot name','','text',true)}${custom?field('title','Advertisement title','','text',true):''}${custom?field('image_url','Banner image URL','','url',false):''}${custom?textarea('body','Description','',false):''}${custom?field('target_url','Destination URL','','url',false):field('adsense_slot','AdSense slot ID','','text',true)}${select('placement','Placement',[{id:'top_banner',name:'Header banner'},{id:'home_inline',name:'Homepage'},{id:'mcq_inline',name:'Between MCQs'},{id:'sidebar',name:'Sidebar'},{id:'footer',name:'Footer'}],'home_inline',true)}${field('starts_at','Start date/time','','datetime-local',false)}${field('ends_at','End date/time','','datetime-local',false)}<label class="check-line"><input type="checkbox" name="active" checked> Active</label><button class="btn primary">${custom?'Create advertisement':'Add AdSense slot'}</button></form>`;
 }
 function customAds(){
  const rows=(MCQ.db.ads||[]).filter(x=>x.provider==='custom');
  return heading('Custom advertisements','Create direct brand campaigns. Expired ads automatically stop appearing on public pages.')+adForm('custom')+`<div class="card" style="margin-top:22px"><h3>Custom campaigns</h3>${rows.length?`<div class="table-wrap mobile-cards"><table><thead><tr><th>Name</th><th>Placement</th><th>Status</th><th>Schedule</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr><td data-label="Name"><strong>${e(x.name)}</strong><br><span class="small muted">${e(x.title||'')}</span></td><td data-label="Placement">${e(x.placement)}</td><td data-label="Status">${badge(x.active?'active':'disabled',x.active?'approved':'rejected')}</td><td data-label="Schedule">${UI.date(x.starts_at)} → ${UI.date(x.ends_at)}</td><td><div class="table-actions">${btn(x.active?'Disable':'Enable','ad-toggle','sm',`data-id="${x.id}"`)}${btn('Delete','ad-delete','sm danger',`data-id="${x.id}"`)}</div></td></tr>`).join('')}</tbody></table></div>`:empty('No custom advertisements','Create your first direct campaign above.')}</div>`;
 }
 function adsensePage(){
  const slots=(MCQ.db.ads||[]).filter(x=>x.provider==='adsense');
  return config('adsense')+`<div style="height:22px"></div>`+heading('AdSense slots','Configure supported placements independently. Keep advertising light so learning remains primary.')+adForm('adsense')+`<div class="card" style="margin-top:22px"><h3>Configured slots</h3>${slots.length?`<div class="table-wrap mobile-cards"><table><thead><tr><th>Name</th><th>Slot</th><th>Placement</th><th>Status</th><th>Actions</th></tr></thead><tbody>${slots.map(x=>`<tr><td data-label="Name">${e(x.name)}</td><td data-label="Slot">${e(x.adsense_slot)}</td><td data-label="Placement">${e(x.placement)}</td><td data-label="Status">${badge(x.active?'active':'disabled',x.active?'approved':'rejected')}</td><td><div class="table-actions">${btn(x.active?'Disable':'Enable','ad-toggle','sm',`data-id="${x.id}"`)}${btn('Delete','ad-delete','sm danger',`data-id="${x.id}"`)}</div></td></tr>`).join('')}</tbody></table></div>`:empty('No AdSense slots','Add a slot above after your AdSense account provides the slot ID.')}</div>`;
 }
 function bulkManager(type){
  const configMap={
   'bulk-categories':{title:'Bulk Categories',kind:'taxonomy',help:'One hierarchy per line: Category | Sub Category | Child Category. Sub/child are optional.',example:'Computer Science\nGeneral Knowledge | World GK | Capitals'},
   'bulk-papers':{title:'Bulk Papers',kind:'papers',help:'One Paper per line. Existing names are skipped after trimming/case/spacing normalization.',example:'PPSC\nFPSC\nNTS'},
   'bulk-jobs':{title:'Bulk Jobs',kind:'jobs',help:'One Job per line: Paper ID or exact Paper name | Job name.',example:'PPSC | Computer Operator\nFPSC | Assistant Director'},
   'bulk-years':{title:'Bulk Job Years',kind:'years',help:'One Job Year per line: Job ID or exact Job name | Job Year / paper title.',example:'Computer Operator | 2026 Morning\nAssistant Director | 2025'}
  };
  const x=configMap[type];
  const form=x.kind==='taxonomy'?'bulk-taxonomy':'bulk-entities';
  const s=App.bulkSummaryKey===type?App.bulkSummary:null;
  const summary=s?`<div class="status-grid bulk-summary"><div class="card"><span class="small muted">Total records</span><strong>${s.total||0}</strong></div><div class="card"><span class="small muted">Added</span><strong>${s.added||0}</strong></div><div class="card"><span class="small muted">Already existed / skipped</span><strong>${s.skipped||0}</strong></div><div class="card"><span class="small muted">Failed</span><strong>${s.failed||0}</strong></div></div>${s.details?.length?`<div class="table-wrap mobile-cards"><table><thead><tr><th>Row</th><th>Result</th><th>Details</th></tr></thead><tbody>${s.details.slice(0,200).map(r=>`<tr><td data-label="Row">${r.row}</td><td data-label="Result">${badge(r.status,r.status==='failed'?'rejected':r.status==='added'?'approved':'pending')}</td><td data-label="Details">${e(r.message)}</td></tr>`).join('')}</tbody></table></div>`:''}`:''; 
  return heading(x.title,x.help)+`<div class="card bulk-manager"><div class="notice">Duplicates are skipped; valid rows continue even when another row fails. The server validates each row and preserves existing records.</div><form data-form="${form}" ${x.kind!=='taxonomy'?`data-type="${x.kind}"`:''}><div class="field"><label for="bulk-rows">Paste records</label><textarea id="bulk-rows" name="rows" rows="12" required placeholder="${e(x.example)}"></textarea></div><button class="btn primary">Import valid records</button></form></div>${summary}`;
 }
 function trash(){MCQ.assert('system');const rows=MCQ.db.trash||[],counts=MCQ.trashCounts(),page=App.page(rows.length),p=App.route.params;const cards=[[counts.mcqs,'Deleted MCQs'],[counts.papers,'Deleted papers'],[counts.jobs,'Deleted jobs'],[counts.years,'Deleted job years'],[counts.categories+counts.subcategories+counts.children,'Deleted category records']];return heading('Trash & recovery','Deleted records stay recoverable with their affected MCQs.')+`<div class="metric-grid">${cards.map(([n,label])=>`<div class="card metric"><p>${label}</p><strong>${n}</strong></div>`).join('')}</div>`+(rows.length?`<div class="table-wrap mobile-cards"><table><thead><tr><th>Deleted record</th><th>Type</th><th>Affected MCQs</th><th>Deleted by</th><th>Deleted</th><th>Action</th></tr></thead><tbody>${rows.slice((page-1)*12,page*12).map(x=>`<tr><td data-label="Deleted record"><strong>${e(x.name)}</strong></td><td data-label="Type">${e(names[x.type]||x.type)}</td><td data-label="Affected MCQs">${(x.mcqs||[]).length}</td><td data-label="Deleted by">${e(x.deleted_by||'—')}</td><td data-label="Deleted">${UI.date(x.deleted_at)}</td><td>${btn('Recover','trash-restore','sm primary',`data-id="${x.id}"`)}</td></tr>`).join('')}</tbody></table></div>${UI.pager(rows.length,page,12,p)}`:empty('Trash is empty','Deleted categories, papers, jobs and their affected MCQs will appear here for recovery.'))}

 function backup(){return heading('Backup & export','Download a safe copy of the connected platform data.')+`<div class="grid"><div class="card"><span class="tile-icon">${icon('download')}</span><h3>Complete platform backup</h3><p>All content, taxonomy, users, reports and progress as JSON.</p><div class="card-foot">${btn('Download backup','backup-export','primary')}</div></div><div class="card"><span class="tile-icon">${icon('book')}</span><h3>MCQ collection</h3><p>Questions with normalized ID arrays for backend integration.</p><div class="card-foot">${btn('Export MCQs','mcqs-export','')}</div></div><div class="card"><span class="tile-icon">${icon('grid')}</span><h3>Category hierarchy</h3><p>Categories, subcategories and child categories as JSON.</p><div class="card-foot">${btn('Export taxonomy','taxonomy-export','')}</div></div></div><div class="card" style="margin-top:25px"></div>`}
 function analytics(){return heading('Collection analytics','Live counts from the data in this browser.')+`<div class="metric-grid">${metrics().slice(0,4).map(([n,l])=>`<div class="card metric"><p>${l}</p><strong>${n}</strong></div>`).join('')}</div><div class="split"><div class="card"><h3>Questions by category</h3>${bars('categories','category_id')}</div><div class="card"><h3>Questions by organization</h3>${bars('papers','paper_id')}</div><div class="card"><h3>Learning activity</h3><p class="callout-number">${MCQ.db.attempts.length}</p><p>Answers checked on this browser</p><p class="small muted">${MCQ.db.bookmarks.length} bookmarks · ${MCQ.db.savedPapers.length} saved papers</p></div><div class="card"><h3>Review status</h3>${['pending','approved','rejected'].map(s=>`<div class="bar-row"><div class="row"><span>${s}</span><span>${MCQ.db.mcqs.filter(q=>q.status===s).length}</span></div><div class="progress-track"><span style="width:${MCQ.db.mcqs.filter(q=>q.status===s).length/MCQ.db.mcqs.length*100}%"></span></div></div>`).join('')}</div></div>`}
 function render(view,id){
  if(!['admin','super-admin'].includes(MCQ.role()))return UI.layout(`<div class="container page">${empty('Access unavailable','Sign in with an Admin or Super Admin account.')}</div>`);
  const superOnly=['users','admins','roles','content','seo','settings','backup','analytics','google-analytics','adsense','custom-ads','duplicates','trash'];
  const permByView={categories:'manage_categories',subcategories:'manage_subcategories',children:'manage_child_categories',papers:'manage_papers',jobs:'manage_jobs',years:'manage_job_years','bulk-categories':'manage_categories','bulk-papers':'manage_papers','bulk-jobs':'manage_jobs','bulk-years':'manage_job_years',guides:'manage_guides',posts:'manage_posts',reports:'view_reports',import:'bulk_import_mcqs',add:'add_mcq'};
  const denied=(App.route.path.startsWith('super-admin')&&MCQ.role()!=='super-admin')||(superOnly.includes(view)&&MCQ.role()!=='super-admin')||(permByView[view]&&!can(permByView[view]));
  if(denied)return shell(empty('Access limited','Your account does not have permission to open this management page.'),'Access limited');
  let body;let title=view;
  if(view==='overview')body=overview();
  else if(['mcqs','pending','approved','rejected','duplicates'].includes(view))body=mcqs(view);
  else if(view==='add'||view==='edit')body=form(id);
  else if(names[view])body=entities(view);
  else if(view==='import')body=importPage();
  else if(['bulk-categories','bulk-papers','bulk-jobs','bulk-years'].includes(view))body=bulkManager(view);
  else if(view==='users'||view==='admins')body=users(view);
  else if(view==='reports')body=reports();
  else if(view==='guides')body=guideManager();
  else if(view==='posts')body=postManager();
  else if(['roles','settings','seo','content','google-analytics'].includes(view))body=config(view);
  else if(view==='adsense')body=adsensePage();
  else if(view==='custom-ads')body=customAds();
  else if(view==='activity')body=heading(MCQ.role()==='admin'?'My activity':'Activity logs','Important administrative changes with date and time.')+`<div class="card">${logs(100)}</div>`;
  else if(view==='trash')body=trash();
  else if(view==='backup')body=backup();
  else if(view==='analytics')body=analytics();
  else body=empty('Page not found');
  return shell(body,names[view]||view.replaceAll('-',' ').replace(/^./,x=>x.toUpperCase()));
 }
 return {render,url,pickerDefs,picker,showPicker,pick,syncDraft,refreshPickers,entityModal,entityState,userModal,guideModal,postModal,loadFile,importPreview};
})();
